package com.fakelegacy.order.web;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.repo.OrderRepository;
import com.fakelegacy.order.service.OrderManager;
import com.fakelegacy.order.web.ApiRequests.PayRequest;
import com.fakelegacy.order.web.ApiRequests.StatusRequest;

@RestController
public class OrderController {

    @Autowired
    private OrderRepository orders;
    @Autowired
    private OrderManager orderManager;

    // O5
    @GetMapping("/orders/{id}")
    public ResponseEntity<Order> get(@PathVariable("id") Long id) {
        return orders.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());
    }

    // O6
    @PostMapping("/orders/{id}/pay")
    public ResponseEntity<Order> pay(@PathVariable("id") Long id, @RequestBody PayRequest req) {
        Order order = orderManager.pay(id, req);
        if (order == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(order);
    }

    // O7: catch-all endpoint, action is APPROVE, REJECT, SHIP or DELIVER
    @PutMapping("/orders/{id}/status")
    public ResponseEntity<Order> status(@PathVariable("id") Long id, @RequestBody StatusRequest req) {
        Order order = orderManager.changeStatus(id, req.action());
        if (order == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(order);
    }

    // O8
    @PostMapping("/orders/{id}/cancel")
    public ResponseEntity<Map<String, Object>> cancel(@PathVariable("id") Long id) {
        Map<String, Object> result = orderManager.cancel(id);
        if (result == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(result);
    }

    // O10: history, or with stats=true the figures customer-service and catalog-service need
    @GetMapping("/customers/{id}/orders")
    public Object history(@PathVariable("id") Long customerId,
            @RequestParam(name = "stats", defaultValue = "false") boolean stats) {
        if (!stats) {
            return orders.findByCustomerIdOrderByCreatedAtDesc(customerId);
        }
        LocalDateTime since = LocalDateTime.now().minusDays(365);
        BigDecimal gross = orders.sumCountedGoodsHtSince(customerId, since);
        BigDecimal returned = orders.sumReturnedGoodsHtSince(customerId, since);
        BigDecimal revenue = gross.subtract(returned).max(BigDecimal.ZERO);

        Map<String, Object> res = new LinkedHashMap<>();
        res.put("customerId", customerId);
        res.put("revenue12m", revenue);
        res.put("activeOrderCount", orders.countActiveOrders(customerId));
        return res;
    }
}
